		AND s.ranking_type = #{rankingType}


		AND s.period_start = #{periodStart}


		AND s.period_end = #{periodEnd}


		AND s.status = #{status}


order by s.ranking_type, s.period_start desc, s.rank_no

select s.work_id, s.view_count
from sys_ranking_snapshot s
inner join (
	select max(period_end) as max_period_end
	from sys_ranking_snapshot
	where ranking_type = #{rankingType}
	  and period_end < #{periodStart}
	  and status = 1
) t on s.period_end = t.max_period_end
where s.ranking_type = #{rankingType}
  and s.status = 1

mapper.update:
update sys_ranking_snapshot
set status = 0,
    update_by = 'system-recompute',
    update_time = sysdate()
where ranking_type = #{rankingType}
  and period_start = #{periodStart}
  and period_end = #{periodEnd}
